def blob(p): return subprocess.check_output(["git", "hash-object", p]).decode().strip()
for f, hs in HUNKS.items():
    t = open(f, encoding="utf-8").read()
    for i, (o, n) in enumerate(hs):
        if t.count(o) != 1: sys.exit(f"ABORT {f} hunk {i}: expected 1 match, found {t.count(o)}")
        t = t.replace(o, n)
    open(f, "w", encoding="utf-8", newline="").write(t)
    if blob(f) != SHA[f]: sys.exit(f"ABORT {f}: sha {blob(f)} != {SHA[f]}")
    print("ok", f, blob(f))
